import java.util.Scanner; import java.util.HashSet; import java.util.Set; public class TestClass { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int n = sc.nextInt(); long[] a = new long[n]; for (int i = 0; i < n; i++) { a[i] = sc.nextLong(); } Set<Long> uniqueMaxSums = new HashSet<Long>(); for (int i = 0; i < n; i++) { for (int j = i; j < n; j++) { long currentMax = Long.MIN_VALUE; long currentSum = 0; for (int k = i; k <= j; k++) { currentSum += a[k]; if (currentSum > currentMax) { currentMax = currentSum; } if (currentSum < 0) { currentSum = 0; } } uniqueMaxSums.add(currentMax); } } long totalSum = 0; for (Long val : uniqueMaxSums) { totalSum += val; } System.out.println(totalSum); } }